
const W=472,H=523,TRAY=540,CH=1040,ZOOM=1.2;
const IMGS={"0": "data:image/png;base64,", "1": "data:image/png;base64,", "2": "data:image/png;base64,", "3": "data:image/png;base64,", "4": "data:image/png;base64,", "5": "data:image/png;base64,", "6": "data:image/png;base64,", "7": "data:image/png;base64,", "8": "data:image/png;base64,", "9": "data:image/png;base64,", "10": "data:image/png;base64,", "11": "data:image/png;base64,", "12": "data:image/png;base64,", "13": "data:image/png;base64,", "14": "data:image/png;base64,", "15": "data:image/png;base64,"};
const INIT=[{"i": 0, "n": "a00", "x": 60, "y": 560, "sc": 0.3}, {"i": 1, "n": "a01", "x": 156, "y": 560, "sc": 0.3}, {"i": 2, "n": "a02", "x": 252, "y": 560, "sc": 0.3}, {"i": 3, "n": "a03", "x": 348, "y": 560, "sc": 0.3}, {"i": 4, "n": "a04", "x": 444, "y": 560, "sc": 0.3}, {"i": 5, "n": "a05", "x": 60, "y": 670, "sc": 0.3}, {"i": 6, "n": "a06", "x": 156, "y": 670, "sc": 0.3}, {"i": 7, "n": "a07", "x": 252, "y": 670, "sc": 0.3}, {"i": 8, "n": "a08", "x": 348, "y": 670, "sc": 0.3}, {"i": 9, "n": "a09", "x": 444, "y": 670, "sc": 0.3}, {"i": 10, "n": "a10", "x": 60, "y": 780, "sc": 0.3}, {"i": 11, "n": "a11", "x": 156, "y": 780, "sc": 0.3}, {"i": 12, "n": "a12", "x": 252, "y": 780, "sc": 0.3}, {"i": 13, "n": "a13", "x": 348, "y": 780, "sc": 0.3}, {"i": 14, "n": "a14", "x": 444, "y": 780, "sc": 0.3}, {"i": 15, "n": "a15", "x": 60, "y": 890, "sc": 0.3}];
const cv=document.getElementById('cv'),ctx=cv.getContext('2d');
cv.width=W*ZOOM;cv.height=CH*ZOOM;
let parts=INIT.map(p=>({...p,flip:false,rot:0,visible:true}));
let sel=parts[0], dragging=false, off={x:0,y:0}, MIRROR=true;
const imgs={};
function loadAll(done){let n=0;const ks=Object.keys(IMGS);
 ks.forEach(k=>{const im=new Image();im.onload=()=>{if(++n===ks.length)done()};im.onerror=()=>{if(++n===ks.length)done()};im.src=IMGS[k];imgs[k]=im;});}
function draw(){
 ctx.setTransform(1,0,0,1,0,0); ctx.clearRect(0,0,cv.width,cv.height);
 ctx.fillStyle='#0e141d';ctx.fillRect(0,0,cv.width,cv.height);
 if(MIRROR){ctx.translate(cv.width,0);ctx.scale(-1,1);}
 ctx.strokeStyle='rgba(60,90,120,0.16)';ctx.lineWidth=1;
 for(let x=0;x<=W;x+=40){ctx.beginPath();ctx.moveTo(x*ZOOM,0);ctx.lineTo(x*ZOOM,H*ZOOM);ctx.stroke();}
 for(let y=0;y<=H;y+=40){ctx.beginPath();ctx.moveTo(0,y*ZOOM);ctx.lineTo(W*ZOOM,y*ZOOM);ctx.stroke();}
 ctx.fillStyle='#0a0f17';ctx.fillRect(0,TRAY*ZOOM,cv.width,cv.height-TRAY*ZOOM);
 ctx.strokeStyle='#1e2a3a';ctx.beginPath();ctx.moveTo(0,TRAY*ZOOM);ctx.lineTo(cv.width,TRAY*ZOOM);ctx.stroke();
 for(const p of parts){
  if(!p.visible)continue;
  const im=imgs[p.i];if(!im||!im.complete||!im.naturalWidth)continue;
  ctx.save();ctx.translate(p.x*ZOOM,p.y*ZOOM);ctx.rotate(p.rot*Math.PI/180);
  ctx.scale(p.flip?-p.sc:p.sc,p.sc);ctx.drawImage(im,-im.width/2,-im.height/2);ctx.restore();
  if(p===sel){const w=im.width*p.sc*ZOOM,h=im.height*p.sc*ZOOM;
   ctx.save();ctx.translate(p.x*ZOOM,p.y*ZOOM);ctx.rotate(p.rot*Math.PI/180);
   ctx.strokeStyle='#4fb8ff';ctx.lineWidth=1.4;ctx.setLineDash([6,4]);ctx.strokeRect(-w/2,-h/2,w,h);ctx.restore();}
 }
 drawMini();
}
function drawMini(){
 const mc=document.getElementById('mini'),m=mc.getContext('2d');
 m.setTransform(1,0,0,1,0,0);m.fillStyle='#0e141d';m.fillRect(0,0,mc.width,mc.height);
 const used=parts.filter(p=>p.visible&&p.y<TRAY-10);
 if(!used.length)return;
 let mnX=1e9,mnY=1e9,mxX=-1e9,mxY=-1e9;const pl=[];
 for(const p of used){const im=imgs[p.i];if(!im||!im.naturalWidth)continue;
  const w=im.width*p.sc,h=im.height*p.sc;pl.push({p,im,w,h});
  mnX=Math.min(mnX,p.x-w/2);mxX=Math.max(mxX,p.x+w/2);mnY=Math.min(mnY,p.y-h/2);mxY=Math.max(mxY,p.y+h/2);}
 if(!pl.length)return;
 const bw=mxX-mnX,bh=mxY-mnY,k=150/bw;
 m.save();m.translate((mc.width-150)/2+150,(mc.height-bh*k)/2);m.scale(-1,1);
 for(const {p,im} of pl){m.save();m.translate((p.x-mnX)*k,(p.y-mnY)*k);m.rotate(p.rot*Math.PI/180);
  m.scale(p.flip?-(p.sc*k):(p.sc*k),p.sc*k);m.drawImage(im,-im.width/2,-im.height/2);m.restore();}
 m.restore();
}
function toCanvas(e){const r=cv.getBoundingClientRect();let x=(e.clientX-r.left)/ZOOM;const y=(e.clientY-r.top)/ZOOM;if(MIRROR)x=W-x;return{x,y};}
function pick(pt){for(let i=parts.length-1;i>=0;i--){const p=parts[i];if(!p.visible)continue;const im=imgs[p.i];if(!im||!im.naturalWidth)continue;
 const dx=pt.x-p.x,dy=pt.y-p.y,a=-p.rot*Math.PI/180;
 const lx=dx*Math.cos(a)-dy*Math.sin(a),ly=dx*Math.sin(a)+dy*Math.cos(a);
 if(Math.abs(lx)<im.width*p.sc/2&&Math.abs(ly)<im.height*p.sc/2)return p;}return null;}
cv.addEventListener('mousedown',e=>{const pt=toCanvas(e);const hit=pick(pt);
 if(hit){sel=hit;dragging=true;off={x:pt.x-hit.x,y:pt.y-hit.y};cv.classList.add('dragging');syncUI();draw();}});
window.addEventListener('mousemove',e=>{if(!dragging||!sel)return;const pt=toCanvas(e);sel.x=Math.round(pt.x-off.x);sel.y=Math.round(pt.y-off.y);syncProps();draw();});
window.addEventListener('mouseup',()=>{dragging=false;cv.classList.remove('dragging');});
cv.addEventListener('wheel',e=>{if(!sel)return;e.preventDefault();sel.sc=Math.max(0.05,Math.min(1.2,sel.sc*(e.deltaY<0?1.06:0.94)));syncProps();draw();},{passive:false});
window.addEventListener('keydown',e=>{if(!sel)return;const st=e.shiftKey?10:1;
 if(e.key==='ArrowLeft')sel.x-=st;else if(e.key==='ArrowRight')sel.x+=st;
 else if(e.key==='ArrowUp')sel.y-=st;else if(e.key==='ArrowDown')sel.y+=st;
 else if(e.key==='q'||e.key==='Q')sel.rot-=2;else if(e.key==='e'||e.key==='E')sel.rot+=2;
 else if(e.key==='f'||e.key==='F')sel.flip=!sel.flip;
 else if(e.key==='h'||e.key==='H')sel.visible=!sel.visible;
 else if(e.key==='['){const i=parts.indexOf(sel);if(i>0){parts.splice(i,1);parts.splice(i-1,0,sel);syncUI();}}
 else if(e.key===']'){const i=parts.indexOf(sel);if(i<parts.length-1){parts.splice(i,1);parts.splice(i+1,0,sel);syncUI();}}
 else return;e.preventDefault();syncProps();draw();});
function syncUI(){const list=document.getElementById('list');list.innerHTML='';
 [...parts].reverse().forEach(p=>{const d=document.createElement('div');
  const st=p.y<TRAY-10;
  d.className='item'+(p===sel?' sel':'');d.textContent=(st?'● ':'　')+p.n+(p.visible?'':'（隱藏）');
  d.style.opacity=p.visible?(st?1:0.55):0.3;
  d.onclick=()=>{sel=p;syncUI();draw();};list.appendChild(d);});syncProps();}
function syncProps(){document.getElementById('px').value=sel.x;document.getElementById('py').value=sel.y;
 document.getElementById('psc').value=sel.sc;document.getElementById('pscn').value=sel.sc.toFixed(3);
 document.getElementById('prot').value=sel.rot;document.getElementById('protn').value=sel.rot;}
['px','py'].forEach(id=>document.getElementById(id).addEventListener('input',e=>{sel[id==='px'?'x':'y']=parseFloat(e.target.value)||0;draw();}));
document.getElementById('psc').addEventListener('input',e=>{sel.sc=parseFloat(e.target.value);document.getElementById('pscn').value=sel.sc.toFixed(3);draw();});
document.getElementById('pscn').addEventListener('input',e=>{sel.sc=parseFloat(e.target.value)||0.3;document.getElementById('psc').value=sel.sc;draw();});
document.getElementById('prot').addEventListener('input',e=>{sel.rot=parseFloat(e.target.value);document.getElementById('protn').value=sel.rot;draw();});
document.getElementById('protn').addEventListener('input',e=>{sel.rot=parseFloat(e.target.value)||0;document.getElementById('prot').value=sel.rot;draw();});
document.getElementById('btnMirror').onclick=e=>{MIRROR=!MIRROR;e.target.textContent=MIRROR?'鏡像：開':'鏡像：關';draw();};
document.getElementById('btnExport').onclick=()=>{
 const used=parts.filter(p=>p.visible&&p.y<TRAY-10);
 const out={size:[W,H],placements:used.map(p=>[p.i,p.x,p.y,+p.sc.toFixed(3),!!p.flip,p.rot])};
 const ta=document.getElementById('out');ta.classList.add('on');ta.value=JSON.stringify(out);ta.select();
 try{document.execCommand('copy')}catch(e){}};
loadAll(()=>{syncUI();draw();document.getElementById('stage').scrollTop=150;});
